"""Lead scoring with clear rules: every point a lead gets comes with the reason, so sales can see why and tune it.

Added by the "Lead scoring with research" template. Change the rules below to fit your market; the thresholds are
settings on the block.
"""

import re

from agentcanvas.sdk import canvas_node

FREE_EMAIL = {"gmail.com", "yahoo.com", "hotmail.com", "outlook.com", "icloud.com", "aol.com", "proton.me", "gmx.de"}
SENIOR = ("chief", "ceo", "cto", "coo", "cfo", "founder", "owner", "president", "vp", "head of", "director")
MANAGER = ("manager", "lead", "principal", "senior")
BUDGET = ("budget", "approved", "funded", "funding", "purchase order", "procurement")
TIMELINE = (
    "this quarter",
    "next month",
    "weeks",
    "asap",
    "deadline",
    "by the end of",
    "before the end of",
    "before our",
    "urgent",
)
NOT_BUYING = ("student", "school project", "thesis", "just curious", "looking for a job", "internship")


def _size(value) -> int:
    """The company size as a number: 120, "120", "51-200" (the first number) or "about 2,000 people"."""
    found = re.search(r"\d[\d,]*", str(value or ""))
    return int(found.group().replace(",", "")) if found else 0


@canvas_node(
    name="templates.score_lead",
    label="Score lead",
    category="Sales",
    icon="list-checks",
    description="Scores an inbound lead from 0 to 100 with clear rules (company size, role, budget, timeline, email) "
    "and sorts it into hot, warm or cold, with the reason for every point.",
    config={
        "type": "object",
        "properties": {
            "hot_at": {
                "type": "integer",
                "title": "Hot from",
                "minimum": 1,
                "maximum": 100,
                "default": 70,
                "description": "A score at or above this is a hot lead.",
            },
            "warm_at": {
                "type": "integer",
                "title": "Warm from",
                "minimum": 1,
                "maximum": 100,
                "default": 40,
                "description": "A score at or above this (and below Hot from) is a warm lead.",
            },
        },
    },
    reads=["lead"],
    writes=["score", "tier", "score_reasons"],
)
def score_lead(state: dict, cfg: dict) -> dict:
    """Score the lead in `lead` (a form submission: name, email, company, role, company_size, message)."""
    lead = state.get("lead") or {}
    if not isinstance(lead, dict):
        lead = {"message": str(lead)}
    role = str(lead.get("role") or "").lower()
    message = str(lead.get("message") or "").lower()
    domain = str(lead.get("email") or "").rpartition("@")[2].lower()
    size = _size(lead.get("company_size"))

    points: list[tuple[int, str]] = []
    if size >= 500:
        points.append((25, f"large company ({size} people)"))
    elif size >= 100:
        points.append((20, f"mid-size company ({size} people)"))
    elif size >= 20:
        points.append((10, f"small company ({size} people)"))
    elif size:
        points.append((3, f"very small company ({size} people)"))
    if any(word in role for word in SENIOR):
        points.append((25, f"decision maker ({lead.get('role')})"))
    elif any(word in role for word in MANAGER):
        points.append((15, f"manager-level contact ({lead.get('role')})"))
    elif role:
        points.append((5, f"individual contributor ({lead.get('role')})"))
    if any(word in message for word in BUDGET):
        points.append((20, "mentions a budget"))
    if any(word in message for word in TIMELINE):
        points.append((15, "has a timeline"))
    if domain and domain not in FREE_EMAIL:
        points.append((15, f"work email ({domain})"))
    elif domain:
        points.append((-10, f"personal email ({domain})"))
    if any(word in message or word in role for word in NOT_BUYING):
        points.append((-25, "not looking to buy (student, job seeker or just curious)"))

    score = max(0, min(100, sum(p for p, _ in points)))
    hot_at, warm_at = int(cfg.get("hot_at") or 70), int(cfg.get("warm_at") or 40)
    tier = "hot" if score >= hot_at else "warm" if score >= warm_at else "cold"
    reasons = [f"{p:+d} {why}" for p, why in points] or ["no signals in the form"]
    return {"score": score, "tier": tier, "score_reasons": reasons}

