"""Research tools for sales agents: a company's profile, its recent news, and our past contact with it.

Added by the "Lead scoring with research" template. They answer from the sample records below; replace each
body with a call to your CRM or data provider (keep the name, arguments and docstring: the agent reads them).
"""

from langchain_core.tools import tool

PROFILES = {
    "northwind traders": "Northwind Traders: food wholesale, 1,200 employees, headquartered in Seattle. Runs its "
    "finance on SAP; invoice approvals are still done by email across 14 warehouses.",
    "contoso": "Contoso Ltd: logistics software, 450 employees, offices in London and Berlin. Grew 40% last year; "
    "hiring a second operations team.",
    "fabrikam": "Fabrikam Inc: furniture maker, 80 employees, one factory in Ohio. Family owned.",
}
NEWS = {
    "northwind traders": "Oct 2026: Northwind Traders announced an external audit of its accounts payable before "
    "year end. Sep 2026: opened two new warehouses in Oregon.",
    "contoso": "Oct 2026: Contoso raised a $30M Series C to expand in Europe.",
}
CONTACTS = {
    "northwind.example": "2025-03: downloaded the 'Invoice automation checklist'. No sales conversation yet.",
    "contoso.example": "2026-06: a demo with their IT lead; they paused it for budget reasons.",
}


def _key(name: str) -> str:
    return " ".join(name.lower().replace(",", " ").replace(".", " ").split())


@tool
def company_profile(company: str) -> str:
    """Look up a company's industry, size, location and the tools it uses. Pass the company's name."""
    key = _key(company)
    found = next((v for k, v in PROFILES.items() if k in key or key in k), None) if key else None
    return found or f"No profile on file for '{company}'. Rely on what the lead wrote."


@tool
def company_news(company: str) -> str:
    """Find a company's recent news (funding, expansion, audits, leadership changes). Pass the company's name."""
    key = _key(company)
    found = next((v for k, v in NEWS.items() if k in key or key in k), None) if key else None
    return found or f"No recent news found for '{company}'."


@tool
def past_contacts(email_domain: str) -> str:
    """Our earlier contact with a company (downloads, demos, deals), found by its email domain, e.g. contoso.com."""
    domain = email_domain.lower().strip().lstrip("@").rpartition("@")[2]
    return CONTACTS.get(domain) or f"No earlier contact with '{domain}' in the CRM."

