"""Evaluator for the "Lead scoring with research" template: scores you can trust, and an email for every hot lead.

Used by the "Score explained, hot leads get an email" evaluator on the Evaluation page.
"""


def check(sample: dict) -> dict:
    """1 when the score is 0-100 with its reasons, and a hot lead has a drafted email; 0 otherwise."""
    out = sample.get("output") or {}
    score, reasons = out.get("score"), out.get("score_reasons") or []
    if not isinstance(score, int) or not 0 <= score <= 100:
        return {"score": 0, "comment": f"the score is not a number from 0 to 100: {score!r}"}
    if not reasons:
        return {"score": 0, "comment": "the score has no reasons"}
    if out.get("tier") == "hot":
        email = str((out.get("structured_response") or {}).get("email") or "").strip()
        if not email:
            return {"score": 0, "comment": "a hot lead got no drafted email"}
        return {"score": 1, "comment": f"scored {score} with {len(reasons)} reasons; email drafted"}
    return {"score": 1, "comment": f"scored {score} with {len(reasons)} reasons"}
